import * as TrueForgeTypes from "../../src/api/index";
import { TrueForge } from "../../src/Client";
import { mockServerPool } from "../mock-server/MockServerPool";

describe("ServerClient", () => {
    test("get_capabilities (1)", async () => {
        const server = mockServerPool.createServer();
        const client = new TrueForge({ maxRetries: 0, token: "test", baseUrl: server.baseUrl });

        const rawResponseBody = {
            data: {
                sandbox: { enabled: true },
                settings: { enabled: true },
                skill: { enabled: true, reason: "reason" },
            },
        };

        server
            .mockEndpoint()
            .get("/api/v1/capabilities")
            .respondWith()
            .statusCode(200)
            .jsonBody(rawResponseBody)
            .build();

        const response = await client.server.getCapabilities();
        expect(response).toEqual({
            data: {
                sandbox: {
                    enabled: true,
                },
                settings: {
                    enabled: true,
                },
                skill: {
                    enabled: true,
                    reason: "reason",
                },
            },
        });
    });

    test("get_capabilities (2)", async () => {
        const server = mockServerPool.createServer();
        const client = new TrueForge({ maxRetries: 0, token: "test", baseUrl: server.baseUrl });

        const rawResponseBody = { error: { message: "message" } };

        server
            .mockEndpoint()
            .get("/api/v1/capabilities")
            .respondWith()
            .statusCode(401)
            .jsonBody(rawResponseBody)
            .build();

        await expect(async () => {
            return await client.server.getCapabilities();
        }).rejects.toThrow(TrueForgeTypes.UnauthorizedError);
    });
});
